CLAUDE_CODE_HOOK_SH = '#!/bin/sh\n# Votal Shield fail-closed hook for Claude Code (PreToolUse).\n# Spec: docs/specs/agent-hook-adapter.md, section 4.3.\n#\n# Claude Code runs this before every matched tool call and pipes the call\'s\n# JSON on stdin. It is forwarded to Shield (POST /v1/shield/hooks/claude-code)\n# and Shield\'s answer is turned into Claude Code\'s:\n#\n#   allow  ({})           -> exit 0, no output\n#   deny                  -> exit 2, reason on stderr (Claude Code shows it)\n#   ask                   -> exit 0, an "ask" decision on stdout\n#   anything else         -> exit 2\n#\n# Claude Code lets a call through when a hook exits with any code other than\n# 2 (checked in task 0). So EVERY failure here exits 2: no config, no curl,\n# Shield unreachable or slow, any non-200, an answer that is not one of the\n# three above. Deploy it with "|| exit 2" after the command, so a missing or\n# unrunnable script denies too:\n#\n#   "command": "/bin/sh \'/Library/Application Support/Votal/claude_code_hook.sh\' || exit 2"\n#\n# Settings come from a root-owned config file, never from the environment\n# (Claude Code\'s environment is the user\'s). Default locations:\n#   macOS  /Library/Application Support/Votal/hook.conf\n#   Linux  /etc/votal/hook.conf\n# or --config <path> as the first argument (fixed by the admin in the\n# managed setting). Format, one per line, # for comments:\n#   SHIELD_URL=https://api.guardrails.votal.ai\n#   SHIELD_API_KEY=<tenant key with the runtime scope>\n#   SHIELD_AGENT=claude-code          (optional, default claude-code)\n#   SHIELD_TIMEOUT=4                  (optional, seconds, 1 to 30; keep it\n#                                      below the hook\'s timeout in settings)\n#   ON_UNREACHABLE=deny               (optional: deny, the default, or allow;\n#                                      what a FAILURE means. Shield\'s own\n#                                      denials always deny.)\n#   SHIELD_LOCAL_SECRET_FILE=<path>   (set by the Votal device agent: ask the\n#                                      agent on 127.0.0.1 with its local secret\n#                                      instead of Shield with a tenant key;\n#                                      docs/specs/claude-code-fleet-rollout.md)\n#\n# Needs only sh, curl, sed, tr and mktemp: no Python, which on a Mac without\n# developer tools is a stub that fails, and would fail open.\n\ndeny() {\n    printf \'Blocked by Votal Shield: %s\\n\' "$1" >&2\n    exit 2\n}\n\n# A failure (no answer, bad answer, bad setup): denied unless the config says\n# ON_UNREACHABLE=allow. Shield\'s own denials go through deny(), never here.\nON_UNREACHABLE=deny\nfail() {\n    if [ "$ON_UNREACHABLE" = "allow" ]; then\n        printf \'Votal Shield: %s; allowed, because this fleet lets actions through when Shield cannot answer\\n\' "${1%, so this action is not allowed}" >&2\n        exit 0\n    fi\n    deny "$1"\n}\n\nCONF=""\nif [ "${1:-}" = "--config" ]; then\n    CONF="${2:-}"\nelif [ "$(uname -s 2>/dev/null)" = "Darwin" ]; then\n    CONF="/Library/Application Support/Votal/hook.conf"\nelse\n    CONF="/etc/votal/hook.conf"\nfi\n[ -n "$CONF" ] && [ -r "$CONF" ] || deny "hook config $CONF is missing or unreadable, so this action is not allowed"\n\n# Parse KEY=value lines; never source the file.\nURL="" KEY="" AGENT="claude-code" TIMEOUT="4" SECRET_FILE="" UNREACH="deny"\nwhile IFS= read -r line || [ -n "$line" ]; do\n    line=$(printf \'%s\' "$line" | tr -d \'\\r\')\n    case "$line" in\n        \'\'|\'#\'*) continue ;;\n    esac\n    k=${line%%=*}\n    v=${line#*=}\n    [ "$k" = "$line" ] && continue\n    k=$(printf \'%s\' "$k" | tr -d \' \\t\')\n    v=$(printf \'%s\' "$v" | sed -e \'s/^[[:space:]]*//\' -e \'s/[[:space:]]*$//\' \\\n                               -e \'s/^"\\(.*\\)"$/\\1/\' -e "s/^\'\\(.*\\)\'$/\\1/")\n    case "$k" in\n        SHIELD_URL) URL=$v ;;\n        SHIELD_API_KEY) KEY=$v ;;\n        SHIELD_AGENT) AGENT=$v ;;\n        SHIELD_TIMEOUT) TIMEOUT=$v ;;\n        SHIELD_LOCAL_SECRET_FILE) SECRET_FILE=$v ;;\n        ON_UNREACHABLE) UNREACH=$v ;;\n    esac\ndone < "$CONF"\n[ "$UNREACH" = "allow" ] && ON_UNREACHABLE=allow\n\n[ -n "$URL" ] || fail "SHIELD_URL is not set in $CONF, so this action is not allowed"\nif [ -n "$SECRET_FILE" ]; then\n    # The Votal device agent on this laptop: loopback only, its local secret.\n    case "$URL" in\n        http://127.0.0.1:*|http://localhost:*) ;;\n        *) fail "SHIELD_URL must be the local agent (http://127.0.0.1:<port>) when SHIELD_LOCAL_SECRET_FILE is set" ;;\n    esac\n    SECRET=$(tr -d \'\\r\\n\' < "$SECRET_FILE" 2>/dev/null)\n    [ -n "$SECRET" ] || fail "the Votal agent\'s local secret could not be read, so this action is not allowed"\nelse\n    [ -n "$KEY" ] || fail "SHIELD_API_KEY is not set in $CONF, so this action is not allowed"\n    case "$URL" in\n        https://*|http://127.0.0.1|http://127.0.0.1[:/]*|http://localhost|http://localhost[:/]*) ;;\n        *) fail "SHIELD_URL must be https (or a localhost address for testing)" ;;\n    esac\nfi\ncase "$TIMEOUT" in\n    \'\'|*[!0-9]*) TIMEOUT=4 ;;\nesac\n[ "$TIMEOUT" -ge 1 ] 2>/dev/null && [ "$TIMEOUT" -le 30 ] || TIMEOUT=4\ncommand -v curl >/dev/null 2>&1 || fail "curl is not installed, so Shield cannot be asked and this action is not allowed"\n\nENDPOINT="${URL%/}/v1/shield/hooks/claude-code"\n[ -n "$SECRET_FILE" ] && ENDPOINT="${URL%/}/v1/local/claude-code/hook"\nUSER_NAME=${USER:-$(id -un 2>/dev/null)}\nHOST_NAME=$(hostname 2>/dev/null)\n\n# Headers go through a private file (curl -H @file) so the key never appears\n# in the process list.\nBODY=$(mktemp "${TMPDIR:-/tmp}/votal-hook.XXXXXX") || fail "could not create a temporary file"\nHDRS=$(mktemp "${TMPDIR:-/tmp}/votal-hook.XXXXXX") || { rm -f "$BODY"; fail "could not create a temporary file"; }\ntrap \'rm -f "$BODY" "$HDRS"\' EXIT HUP INT TERM\nchmod 600 "$HDRS" "$BODY"\n{\n    if [ -n "$SECRET_FILE" ]; then\n        printf \'X-Votal-Local-Secret: %s\\n\' "$SECRET"\n    else\n        printf \'X-API-Key: %s\\n\' "$KEY"\n        printf \'X-Agent-Key: %s\\n\' "$AGENT"\n        printf \'X-Device-Id: %s\\n\' "$HOST_NAME"\n    fi\n    printf \'X-Shield-User: %s\\n\' "$USER_NAME"\n    printf \'Content-Type: application/json\\n\'\n} > "$HDRS"\n\nSTATUS=$(curl -sS --max-time "$TIMEOUT" --connect-timeout "$TIMEOUT" \\\n              -H @"$HDRS" --data-binary @- -o "$BODY" -w \'%{http_code}\' \\\n              "$ENDPOINT" 2>/dev/null) \\\n    || fail "Shield could not be reached at $URL, so this action is not allowed"\n[ "$STATUS" = "200" ] || fail "Shield answered HTTP $STATUS, so this action is not allowed"\n\nANSWER=$(tr -d \'\\r\\n\' < "$BODY")\nCOMPACT=$(printf \'%s\' "$ANSWER" | tr -d \' \\t\')\n\n# The reason Shield gave, made safe to print and to put back into JSON.\nreason() {\n    printf \'%s\' "$ANSWER" \\\n        | sed -n -E \'s/.*"permissionDecisionReason"[[:space:]]*:[[:space:]]*"(([^"\\\\]|\\\\.)*)".*/\\1/p\' \\\n        | sed -e \'s/\\\\"/\'"\'"\'/g\' -e \'s/\\\\[nrt]/ /g\' -e \'s/\\\\//g\' -e \'s/"//g\' \\\n        | tr -d \'\\000-\\037\' | cut -c1-500\n}\n\ncase "$COMPACT" in\n    \'{}\')\n        exit 0 ;;\n    *\'"permissionDecision":"deny"\'*)\n        why=$(reason)\n        why=${why#Blocked by Votal Shield: }\n        deny "${why:-denied by policy}" ;;\n    *\'"permissionDecision":"ask"\'*)\n        why=$(reason)\n        printf \'{"hookSpecificOutput":{"hookEventName":"PreToolUse","permissionDecision":"ask","permissionDecisionReason":"%s"}}\\n\' \\\n            "${why:-Votal Shield: this action needs your confirmation}"\n        exit 0 ;;\nesac\nfail "Shield\'s answer was not understood, so this action is not allowed"\n'

CLAUDE_CODE_HOOK_PS1 = '# Votal Shield fail-closed hook for Claude Code (PreToolUse), Windows.\n# Spec: docs/specs/agent-hook-adapter.md, section 4.3. The twin of\n# claude_code_hook.sh: same config, same answers, same rule that EVERY\n# failure exits 2 (Claude Code lets a call through on any other exit code).\n#\n#   allow  ({})  -> exit 0, no output\n#   deny         -> exit 2, reason on stderr\n#   ask          -> exit 0, an "ask" decision on stdout\n#   anything else, or any error -> exit 2\n#\n# Deploy with "|| exit 2" after the command, so a missing script denies too:\n#   "command": "powershell.exe -NoProfile -NonInteractive -ExecutionPolicy Bypass -File \\"C:\\\\Program Files\\\\Votal\\\\claude_code_hook.ps1\\" || exit 2"\n#\n# Config: C:\\ProgramData\\Votal\\hook.conf (or -Config <path>), KEY=value lines:\n#   SHIELD_URL, SHIELD_API_KEY, SHIELD_AGENT (default claude-code),\n#   SHIELD_TIMEOUT (seconds, 1 to 30, default 4), ON_UNREACHABLE (deny, the\n#   default, or allow: what a FAILURE means; Shield\'s own denials always deny),\n#   SHIELD_LOCAL_SECRET_FILE (set by the Votal device agent: ask the agent on\n#   127.0.0.1 with its local secret instead of Shield with a tenant key).\n#   Never read from the environment. Windows PowerShell 5.1 or later.\n\nparam([string]$Config = "$env:ProgramData\\Votal\\hook.conf")\n\n$ErrorActionPreference = "Stop"\n\nfunction Deny([string]$Why) {\n    [Console]::Error.WriteLine("Blocked by Votal Shield: $Why")\n    exit 2\n}\n\n# A failure (no answer, bad answer, bad setup): denied unless the config says\n# ON_UNREACHABLE=allow. Shield\'s own denials go through Deny, never here.\n$script:OnUnreachable = "deny"\nfunction Fail([string]$Why) {\n    if ($script:OnUnreachable -eq "allow") {\n        [Console]::Error.WriteLine("Votal Shield: $($Why -replace \', so this action is not allowed$\', \'\'); allowed, because this fleet lets actions through when Shield cannot answer")\n        exit 0\n    }\n    Deny $Why\n}\n\ntrap { Fail "the hook failed ($($_.Exception.Message)), so this action is not allowed" }\n\nif (-not (Test-Path -LiteralPath $Config -PathType Leaf)) {\n    Deny "hook config $Config is missing or unreadable, so this action is not allowed"\n}\n\n$settings = @{ SHIELD_URL = ""; SHIELD_API_KEY = ""; SHIELD_AGENT = "claude-code"; SHIELD_TIMEOUT = "4";\n              SHIELD_LOCAL_SECRET_FILE = ""; ON_UNREACHABLE = "deny" }\nforeach ($line in Get-Content -LiteralPath $Config) {\n    $l = $line.Trim()\n    if ($l -eq "" -or $l.StartsWith("#") -or -not $l.Contains("=")) { continue }\n    $k, $v = $l.Split("=", 2)\n    $k = $k.Trim(); $v = $v.Trim()\n    if ($v.Length -ge 2 -and (($v[0] -eq \'"\' -and $v[-1] -eq \'"\') -or ($v[0] -eq "\'" -and $v[-1] -eq "\'"))) {\n        $v = $v.Substring(1, $v.Length - 2)\n    }\n    if ($settings.ContainsKey($k)) { $settings[$k] = $v }\n}\n\nif ($settings.ON_UNREACHABLE -eq "allow") { $script:OnUnreachable = "allow" }\n$url = $settings.SHIELD_URL\n$local = [bool]$settings.SHIELD_LOCAL_SECRET_FILE\nif (-not $url) { Fail "SHIELD_URL is not set in $Config, so this action is not allowed" }\nif ($local) {\n    # The Votal device agent on this laptop: loopback only, its local secret.\n    if (-not ($url -match \'^http://(127\\.0\\.0\\.1|localhost):\\d+/?$\')) {\n        Fail "SHIELD_URL must be the local agent (http://127.0.0.1:<port>) when SHIELD_LOCAL_SECRET_FILE is set"\n    }\n    $secret = ""\n    try { $secret = (Get-Content -LiteralPath $settings.SHIELD_LOCAL_SECRET_FILE -Raw).Trim() } catch { }\n    if (-not $secret) { Fail "the Votal agent\'s local secret could not be read, so this action is not allowed" }\n} else {\n    if (-not $settings.SHIELD_API_KEY) { Fail "SHIELD_API_KEY is not set in $Config, so this action is not allowed" }\n    if (-not ($url -match \'^https://\' -or $url -match \'^http://(127\\.0\\.0\\.1|localhost)([:/]|$)\')) {\n        Fail "SHIELD_URL must be https (or a localhost address for testing)"\n    }\n}\n$timeout = 4\n[int]::TryParse($settings.SHIELD_TIMEOUT, [ref]$timeout) | Out-Null\nif ($timeout -lt 1 -or $timeout -gt 30) { $timeout = 4 }\n\n[Console]::InputEncoding = [System.Text.Encoding]::UTF8\n$body = [Console]::In.ReadToEnd()\n[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12\n\nif ($local) {\n    $headers = @{ "X-Votal-Local-Secret" = $secret; "X-Shield-User" = $env:USERNAME }\n    $endpoint = $url.TrimEnd("/") + "/v1/local/claude-code/hook"\n} else {\n    $headers = @{\n        "X-API-Key"     = $settings.SHIELD_API_KEY\n        "X-Agent-Key"   = $settings.SHIELD_AGENT\n        "X-Shield-User" = $env:USERNAME\n        "X-Device-Id"   = $env:COMPUTERNAME\n    }\n    $endpoint = $url.TrimEnd("/") + "/v1/shield/hooks/claude-code"\n}\ntry {\n    $resp = Invoke-WebRequest -Uri $endpoint -Method Post `\n        -Headers $headers -ContentType "application/json" `\n        -Body ([System.Text.Encoding]::UTF8.GetBytes($body)) -TimeoutSec $timeout -UseBasicParsing\n} catch {\n    $code = $null\n    if ($_.Exception.Response) { $code = [int]$_.Exception.Response.StatusCode }\n    if ($code) { Fail "Shield answered HTTP $code, so this action is not allowed" }\n    Fail "Shield could not be reached at $url, so this action is not allowed"\n}\nif ([int]$resp.StatusCode -ne 200) { Fail "Shield answered HTTP $($resp.StatusCode), so this action is not allowed" }\n\ntry { $answer = $resp.Content | ConvertFrom-Json } catch { Fail "Shield\'s answer was not understood, so this action is not allowed" }\nif ($null -eq $answer) { Fail "Shield\'s answer was not understood, so this action is not allowed" }\n$names = @($answer.PSObject.Properties | ForEach-Object { $_.Name })\nif ($names.Count -eq 0) { exit 0 }                                  # {} = allow\n\n$out = $answer.hookSpecificOutput\n$decision = if ($out) { [string]$out.permissionDecision } else { "" }\n$reason = if ($out) { [string]$out.permissionDecisionReason } else { "" }\n$reason = ($reason -replace \'[\\x00-\\x1f]\', \' \')\nif ($reason.Length -gt 500) { $reason = $reason.Substring(0, 500) }\n\nif ($decision -eq "deny") {\n    $why = $reason -replace \'^Blocked by Votal Shield: \', \'\'\n    if (-not $why) { $why = "denied by policy" }\n    Deny $why\n}\nif ($decision -eq "ask") {\n    if (-not $reason) { $reason = "Votal Shield: this action needs your confirmation" }\n    $ask = @{ hookSpecificOutput = @{ hookEventName = "PreToolUse"; permissionDecision = "ask";\n                                      permissionDecisionReason = $reason } }\n    [Console]::Out.WriteLine(($ask | ConvertTo-Json -Compress -Depth 4))\n    exit 0\n}\nFail "Shield\'s answer was not understood, so this action is not allowed"\n'
